<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElButton, ElDatePicker, ElDialog, ElForm, ElFormItem, ElInput, ElMessage, ElMessageBox, ElOption, ElSelect, ElTag } from 'element-plus'
import { currentUser, httpClient } from '@/shared/http/client'
import CaseSummaryPanel from './CaseSummaryPanel.vue'
import { statusLabels, workOrderApi, type DraftForm, type RegionOption, type WorkOrder, type WorkOrderStatus } from './work-orders'

const api=workOrderApi(httpClient),router=useRouter(),route=useRoute(),loading=ref(false),rows=ref<WorkOrder[]>([]),total=ref(0),page=ref(1),error=ref('')
const status=ref(String(route.query.status??'')),query=ref(String(route.query.query??'')),selected=computed(()=>String(route.query.selected??'')),dialog=ref(false),saving=ref(false),regions=ref<RegionOption[]>([])
const isAdmin=computed(()=>currentUser.value?.roles.includes('ADMIN')===true)
const blank=():DraftForm=>({insuranceCompany:'',claimNo:'',claimReportedAt:'',ownerName:'',ownerPhone:'',policyNo:'',vehicleBrand:'',vehicleModel:'',vehicleVin:'',vehiclePlate:'',vehicleOtherIdentifier:'',accidentAt:'',accidentRegionId:'',accidentAddress:'',accidentDescription:''})
const form=reactive<DraftForm>(blank())
async function load(){loading.value=true;error.value='';try{const result=await api.list(page.value,status.value,query.value.trim());rows.value=result.records;total.value=result.total}catch(cause){error.value=cause instanceof Error?cause.message:'加载失败'}finally{loading.value=false}}
function filter(){page.value=1;void router.replace({path:'/work-orders',query:{...(query.value.trim()?{query:query.value.trim()}:{}),...(status.value?{status:status.value}:{})}});void load()}
function reset(){query.value='';status.value='';filter()}
function select(row:WorkOrder){void router.push({path:'/work-orders',query:{...route.query,selected:row.id}})}
function keySelect(event:KeyboardEvent,row:WorkOrder){if(event.key==='Enter'){event.preventDefault();if(event.ctrlKey||event.metaKey)void router.push(`/work-orders/${row.id}`);else select(row)}}
async function create(){saving.value=true;try{const created=await api.create(form);dialog.value=false;Object.assign(form,blank());ElMessage.success('草稿已创建');await router.push(`/work-orders/${created.id}`)}catch(error){ElMessage.error(error instanceof Error?error.message:'创建失败')}finally{saving.value=false}}
async function configureDuplicates(){try{const current=await api.configuration();const days=await ElMessageBox.prompt('疑似重复的相近/短期天数（1—365）','重复判断配置',{inputValue:String(current.possibleDuplicateDays),inputPattern:/^(?:[1-9]|[1-9]\d|[12]\d\d|3[0-5]\d|36[0-5])$/,inputErrorMessage:'请输入 1—365 的整数'});const reason=await ElMessageBox.prompt('请输入本次修改原因','重复判断配置',{inputValidator:value=>Boolean(value.trim())||'原因必填'});await api.updateConfiguration(Number(days.value),reason.value.trim());ElMessage.success('重复判断时间窗口已更新')}catch(error){if(error instanceof Error&&error.message)ElMessage.error(error.message)}}
onMounted(async()=>{await load();try{regions.value=(await api.regions()).records}catch(error){ElMessage.error(error instanceof Error?error.message:'区域加载失败')}})
watch(()=>route.query.query,value=>{if(String(value??'')!==query.value){query.value=String(value??'');page.value=1;void load()}})
watch(()=>route.query.status,value=>{if(String(value??'')!==status.value){status.value=String(value??'');page.value=1;void load()}})
</script>

<template>
  <ElButton v-if="selected" class="mobile-back" text @click="router.push({path:'/work-orders',query:{...(query?{query}:{}),...(status?{status}:{})}})">← 返回案件队列</ElButton>
  <div class="work-page case-workspace"><header class="case-header"><div><p class="eyebrow">CASE OPERATIONS / 案件中心</p><h1>案件队列</h1><p>筛选并选择案件，右侧查看当前阶段、授权条件和处理历史。</p></div><div class="actions"><ElButton v-if="isAdmin" @click="configureDuplicates">重复判断配置</ElButton><ElButton type="primary" @click="dialog=true">新建草稿</ElButton></div></header>
    <div class="case-columns" :class="{ 'has-selection': selected }"><section class="case-queue" aria-label="案件队列"><form class="filters" @submit.prevent="filter"><ElInput v-model="query" clearable placeholder="案件号 / 报案号 / 手机号" aria-label="案件关键字"/><ElSelect v-model="status" clearable placeholder="全部状态" aria-label="案件状态"><ElOption v-for="(label,key) in statusLabels" :key="key" :label="label" :value="key"/></ElSelect><ElButton type="primary" native-type="submit">筛选</ElButton><ElButton @click="reset">重置</ElButton></form><p class="queue-count">稳定排序 · 第 {{ page }} 页 / 共 {{ total }} 条</p>
      <div v-if="error" class="queue-state" role="alert">{{ error }} <ElButton @click="load">重试</ElButton></div><div v-else-if="loading" class="queue-state" aria-busy="true">正在加载案件…</div><div v-else-if="!rows.length" class="queue-state">当前条件下没有案件。<ElButton text @click="reset">清除筛选</ElButton></div>
      <div v-else class="queue-rows" role="listbox" aria-label="案件结果"><div v-for="row in rows" :key="row.id" class="queue-row" :class="{ 'is-selected': selected===row.id }" role="option" tabindex="0" :aria-selected="selected===row.id" @click="select(row)" @keydown="keySelect($event,row)"><div class="queue-row-top"><strong>{{ row.businessNo || '草稿未编号' }}</strong><ElTag size="small" effect="plain">{{ statusLabels[row.status as WorkOrderStatus] }}</ElTag></div><p>{{ row.vehicleBrand || '未填写品牌' }} {{ row.vehicleModel }} · {{ row.ownerName || '未填写车主' }}</p><small>{{ row.claimNo || '暂无报案号' }} · {{ row.ownerPhone || '未填写手机' }}</small><ElButton text size="small" @click.stop="router.push(`/work-orders/${row.id}`)">完整详情 ↗</ElButton></div></div>
      <div class="pager"><ElButton :disabled="loading||page<=1" @click="page--;load()">上一页</ElButton><span>{{ page }} / {{ Math.max(1,Math.ceil(total/20)) }}</span><ElButton :disabled="loading||page*20>=total" @click="page++;load()">下一页</ElButton></div></section>
      <CaseSummaryPanel v-if="selected" :case-id="selected" class="selected-summary"/><aside v-else class="case-placeholder"><p>选择一个案件</p><h2>让下一步清晰可见</h2><p>右侧将显示真实状态、四项维修授权条件和最近处理记录。复杂操作仍在完整详情中进行。</p></aside></div>
  <ElDialog v-model="dialog" title="新建案件草稿" width="820px"><ElForm label-position="top"><div class="form-grid"><ElFormItem label="保险公司"><ElInput v-model="form.insuranceCompany"/></ElFormItem><ElFormItem label="报案号"><ElInput v-model="form.claimNo"/></ElFormItem><ElFormItem label="报案时间（选填）"><ElDatePicker v-model="form.claimReportedAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></ElFormItem><ElFormItem label="车主姓名"><ElInput v-model="form.ownerName"/></ElFormItem><ElFormItem label="车主手机"><ElInput v-model="form.ownerPhone"/></ElFormItem><ElFormItem label="保单号（选填）"><ElInput v-model="form.policyNo"/></ElFormItem><ElFormItem label="车辆品牌"><ElInput v-model="form.vehicleBrand"/></ElFormItem><ElFormItem label="车辆型号"><ElInput v-model="form.vehicleModel"/></ElFormItem><ElFormItem label="车架号 / VIN"><ElInput v-model="form.vehicleVin"/></ElFormItem><ElFormItem label="车辆牌照"><ElInput v-model="form.vehiclePlate"/></ElFormItem><ElFormItem label="保险认可的其他车辆编号"><ElInput v-model="form.vehicleOtherIdentifier"/></ElFormItem><ElFormItem label="事故时间"><ElDatePicker v-model="form.accidentAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></ElFormItem><ElFormItem label="事故区域"><ElSelect v-model="form.accidentRegionId" filterable placeholder="选择区域"><ElOption v-for="item in regions" :key="item.id" :label="`${item.name}（${item.code}）`" :value="String(item.id)"/></ElSelect></ElFormItem><ElFormItem label="详细地址（选填）"><ElInput v-model="form.accidentAddress"/></ElFormItem><ElFormItem class="wide" label="事故说明"><ElInput v-model="form.accidentDescription" type="textarea"/></ElFormItem></div></ElForm><p class="hint">正式提交时，车架号、车辆牌照、其他车辆编号至少填写一项；案件数据来源和当前负责人由系统填写。</p><template #footer><ElButton @click="dialog=false">取消</ElButton><ElButton type="primary" :loading="saving" @click="create">保存草稿</ElButton></template></ElDialog>
  </div>
</template>

<style scoped>.case-header{display:flex;justify-content:space-between;align-items:end;gap:18px;margin:0 0 20px}.case-header h1{margin:2px 0 4px;font-size:26px}.case-header p:last-child{margin:0}.eyebrow{margin:0;color:var(--color-accent);font-size:10px;font-weight:700;letter-spacing:.14em}.case-columns{display:grid;grid-template-columns:minmax(420px,42%) minmax(0,58%);gap:18px;align-items:start}.case-queue{min-width:0;border:1px solid var(--color-border);border-radius:12px;background:#fff;overflow:hidden}.filters{display:flex;flex-wrap:wrap;gap:8px;padding:16px}.filters .el-input{min-width:160px;flex:1}.filters .el-select{width:140px}.filters .el-button{margin:0}.queue-count{margin:0;padding:0 16px 10px;color:var(--color-text-secondary);font-size:12px}.queue-rows{max-height:calc(100vh - 300px);overflow:auto}.queue-row{position:relative;padding:13px 16px;border-top:1px solid var(--color-border);cursor:pointer}.queue-row:hover,.queue-row:focus-visible{background:var(--color-canvas)}.queue-row.is-selected{background:var(--color-accent-soft)}.queue-row.is-selected::before{position:absolute;top:0;bottom:0;left:0;width:3px;background:var(--color-accent);content:''}.queue-row-top{display:flex;justify-content:space-between;align-items:center;gap:8px}.queue-row p{margin:5px 0 0;font-size:13px}.queue-row small{display:block;color:var(--color-text-secondary)}.queue-row .el-button{margin:4px 0 0;padding:0}.queue-state{padding:42px 16px;color:var(--color-text-secondary)}.pager{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:12px 16px;border-top:1px solid var(--color-border);font-variant-numeric:tabular-nums}.case-placeholder{padding:68px 40px;border:1px dashed var(--color-border-strong);border-radius:14px;color:var(--color-text-secondary)}.case-placeholder h2{color:var(--color-text)}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 20px}.wide{grid-column:1/-1}.hint{color:var(--color-text-secondary)}
@media(max-width:1439px){.case-columns{grid-template-columns:minmax(340px,360px) minmax(0,1fr)}}@media(max-width:1023px){.case-columns{grid-template-columns:1fr}.case-columns.has-selection .case-queue{display:none}.queue-rows{max-height:none}.case-header{align-items:start}}@media(max-width:640px){.case-header{display:block}.case-header .actions{padding:12px 0}.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}}
.mobile-back{display:none}@media(max-width:1023px){.mobile-back{display:inline-flex;margin:8px 0 0}}
</style>
